export const MAGES = {"alzur":{"id":"alzur","hero":"Альзур","title":"Чародей","color":"#3c6fb4","spec":"Молнии","specText":"Один раз за битву: понизьте свой уровень энергии на 1, чтобы бросить кубик. Примените к результату указанный модификатор. Выберите и выполните 1 соответствующий результату эффект:","table":[[-3],[-1],[0],[2],[2]]},"ardea":{"id":"ardea","hero":"Ардея","title":"Чародейка","color":"#c04f8e","spec":"Левитация","specText":"Один раз за битву: увеличьте свой уровень энергии на указанное количество и возьмите указанное количество карт из своей колоды.","table":[[1,0],[1,1],[2,1],[2,2],[2,2]]},"gehira":{"id":"gehira","hero":"Гехира","title":"Чародейка","color":"#4a3a30","spec":"Некромантия","specText":"Один раз за битву: сбросьте 1 карту из руки, чтобы нанести указанное количество урона и увеличить свой уровень энергии на указанное количество.","table":[[1,0],[2,0],[2,1],[3,1],[3,1]]},"otar":{"id":"otar","hero":"Отар","title":"Чародей","color":"#7a4fb0","spec":"Телепортация","specText":"Один раз за битву: в свой первый ход битвы получите указанное количество единиц барьера и увеличьте свой уровень энергии на указанное количество.","table":[[1,0],[1,1],[2,1],[2,2],[2,2]]},"philippa":{"id":"philippa","hero":"Филиппа","title":"Чародейка","color":"#2f9e9a","spec":"Полиморфизм","specText":"Один раз за битву: бросьте кубик и примените к результату указанный модификатор. Выберите и выполните 1 соответствующий результату эффект:","table":[[-3],[-1],[0],[2],[2]]}};
export const MAGE_TROPHIES = [{"id":"MAGE-TROPHY-01","cell":"r1c1","mage":"alzur","flavor":"Короткой стычки хватило, чтобы понять: Альзур и вправду не чурается рисковых экспериментов с Силой. На сей раз ему повезло уцелеть."},{"id":"MAGE-TROPHY-02","cell":"r1c2","mage":"alzur","flavor":"Оказывается, Альзур приложил руку к созданию первых ведьмаков! Что ж, не первый и не последний раз творение оборачивается против своего создателя…"},{"id":"MAGE-TROPHY-03","cell":"r2c1","mage":"alzur","flavor":"Говорят, голос Альзура подобен колоколу, а дикция у него — как у настоящего оратора. Вряд ли он сохранит такую славу — с выбитыми-то зубами!"},{"id":"MAGE-TROPHY-04","cell":"r2c2","mage":"alzur","flavor":"Вы были готовы поклясться, что Альзур, ещё дыша, дал себе клятву — придумать заклятие, способное выиграть любую стычку."},{"id":"MAGE-TROPHY-05","cell":"r1c1","mage":"ardea","flavor":"Когда Ардея свалилась на извачканный пивом и сажей пол корчмы, от очарования и грации выпускницы Аретузы уже не оставалось и следа."},{"id":"MAGE-TROPHY-06","cell":"r1c2","mage":"ardea","flavor":"Чопорная чародейка на деле оказалась птицей невысокого полёта."},{"id":"MAGE-TROPHY-07","cell":"r2c1","mage":"ardea","flavor":"«Мда, летаешь ты неплохо, чародейка. А вот приземляешься не очень, враскоряк…»"},{"id":"MAGE-TROPHY-08","cell":"r2c2","mage":"ardea","flavor":"И зачем стоило тратить годы на обучение искусству левитации? Один ваш пинок — и прекрасно полетела без всякой Силы!"},{"id":"MAGE-TROPHY-09","cell":"r1c1","mage":"gehira","flavor":"В народе некромантов не больно-то уважают. Неудивительно, что в корчме были только рады вашей победе."},{"id":"MAGE-TROPHY-10","cell":"r1c2","mage":"gehira","flavor":"«Вот же ж, уцелела чародейка. А то пришлось бы ей себя из могилы подымать!»"},{"id":"MAGE-TROPHY-11","cell":"r2c1","mage":"gehira","flavor":"Если некромантию считать за разговор со смертью, то после вашей стычки колдунья с ней уже почти на «ты»."},{"id":"MAGE-TROPHY-12","cell":"r2c2","mage":"gehira","flavor":"Не стоило ей выводить вас из себя, ох, не стоило. Докаркалась, как говорится!"},{"id":"MAGE-TROPHY-13","cell":"r1c1","mage":"otar","flavor":"«А говорили — лучший выпускник Бан Арда, да то, да сё…»"},{"id":"MAGE-TROPHY-14","cell":"r1c2","mage":"otar","flavor":"Если верить чародейкам, мужчинам недостаёт мотивации, чтобы должным образом освоить секреты магии. Плачевное последствие такой лени валяется перед вами."},{"id":"MAGE-TROPHY-15","cell":"r2c1","mage":"otar","flavor":"«Чародей, умеешь исцелять себя сам? Очень тебе пригодится в ближайшие дни»."},{"id":"MAGE-TROPHY-16","cell":"r2c2","mage":"otar","flavor":"Судя по гримасе, застывшей на опухшем лице Отара, он предпочёл бы перенестись куда угодно, лишь бы подальше от вас."},{"id":"MAGE-TROPHY-17","cell":"r1c1","mage":"philippa","flavor":"Если бы вас не остановили, Филиппу уже можно было бы причислять к лику святых."},{"id":"MAGE-TROPHY-18","cell":"r1c2","mage":"philippa","flavor":"В городе ещё долго судачили, что ведьма-то мучилась на славу — ни один палач или жрец не придрался бы."},{"id":"MAGE-TROPHY-19","cell":"r2c1","mage":"philippa","flavor":"«Филиппа, если уж желаешь от кого-то избавиться, будь благоразумна — поручи работу тем, кто в этом деле смыслит»."},{"id":"MAGE-TROPHY-20","cell":"r2c2","mage":"philippa","flavor":"При всём своём искусстве полиморфизма Филиппа была вам не ровня — хоть бы она обернулась самой смертью."}];
